import re
from urllib.parse import urlparse
from bs4 import BeautifulSoup
import requests


_URL_PATTERN = re.compile(
    r'(?i)\b((?:https?://|www\.)[^\s<>"\'`]+|(?:[A-Za-z0-9-]+\.)+[A-Za-z]{2,}(?:/[^\s<>"\'`]*)?)'
)


def _clean_url_candidate(candidate: str) -> str:
    # Remove common trailing punctuation that often follows URLs in text.
    return candidate.rstrip(".,;:!?)]}'>\"")


def _normalize_and_validate_url(candidate: str):
    candidate = _clean_url_candidate(candidate)

    if candidate.startswith("www."):
        candidate = "https://" + candidate
    elif not re.match(r"^[a-zA-Z][a-zA-Z0-9+.-]*://", candidate):
        candidate = "http://" + candidate

    parsed = urlparse(candidate)
    if parsed.scheme in ("http", "https") and parsed.netloc:
        return candidate
    return None


def _extract_url(text):
    for match in _URL_PATTERN.finditer(text):
        normalized = _normalize_and_validate_url(match.group(0))
        if normalized:
            return normalized
    return None


def task_func(myString):
    text = "" if myString is None else str(myString)

    url = _extract_url(text)
    if not url:
        return "No valid URL found in the provided string."

    try:
        response = requests.get(
            url,
            timeout=10,
            headers={"User-Agent": "Mozilla/5.0"},
        )
        response.raise_for_status()
    except requests.RequestException:
        return f"Unable to fetch the content of the URL: {url}"

    soup = BeautifulSoup(response.content, "html.parser")
    title_tag = soup.find("title")

    if title_tag is None:
        return "No title tag found in the webpage."

    title = title_tag.get_text(strip=True)
    if not title:
        return "No title tag found in the webpage."

    return title
